export interface StructuredOutputDef {
  formatField: string;
  formatType: string;
  schemaPath: string;
  betaHeader: string;
  enforceStrict: boolean;
  removeAdditionalProps: boolean;
  // "WrappedInFormat" (default): schema nests inside the format object
  // at formatField. "SiblingOfFormat": formatField is set to the literal
  // formatType and schemaPath holds the schema as an independent field.
  schemaPlacement: string;
}

